def load_shops_master(shop_list_path, df):
    if shop_list_path:
        shops = pd.read_excel(shop_list_path)
        records = [
            {
                "code": _sc(r["SHOP CODE"]),
                "name": str(r["SHOP NAME"]).strip(),
                "type": r["TYPE SHOP"],
                "region": r["REGION"],
                "area": r["AREA"],
                "size": r.get("Size Shop", None),
            }
            for _, r in shops.iterrows()
        ]
        return json.dumps(records, ensure_ascii=False)
    shops = df[["SHOP_CODE", "SHOP NAME", "TYPE SHOP", "REGION", "AREA"]].dropna(subset=["SHOP_CODE"]).drop_duplicates(subset=["SHOP_CODE"])
    records = [
        {
            "code": _sc(r["SHOP_CODE"]),
            "name": str(r["SHOP NAME"]).strip(),
            "type": r["TYPE SHOP"],
            "region": r["REGION"],
            "area": r["AREA"],
        }
        for _, r in shops.iterrows()
    ]
    return json.dumps(records, ensure_ascii=False)

def export_group(df, prodgroup, rev_col="NET_AMOUNT"):
    f = df[df["CUSTOM_PRODGROUP"] == prodgroup].copy()
    f = f[["DATE", "REGION", "AREA", "SHOP_CODE", "SHOP NAME", "TYPE SHOP", "QTY", rev_col, "CUSTOM_BRAND", "CUSTOM_SUBBRAND", "CUSTOM_MODEL", "CUSTOM_SUBMODEL"]]
    f["DATE"] = pd.to_datetime(f["DATE"])
    f = f.sort_values(["DATE", "REGION", "AREA", "SHOP NAME"])
    records = [
        {
            "date": r["DATE"].strftime("%Y-%m-%d"),
            "region": r["REGION"],
            "area": r["AREA"],
            "code": _sc(r["SHOP_CODE"]),
            "shop": str(r["SHOP NAME"]).strip(),
            "type": r["TYPE SHOP"],
            "qty": int(r["QTY"]),
            "rev": int(r[rev_col]),
            "brand": r["CUSTOM_BRAND"],
            "subBrand": r["CUSTOM_SUBBRAND"],
            "model": r["CUSTOM_MODEL"],
            "subModel": r["CUSTOM_SUBMODEL"],
        }
        for _, r in f.iterrows()
    ]
    return records, f

def export_suplife_attach(df):
    """Builds row-level records for the 'Attach Suplife PLV' tab: unlike
    the main Attach Rate tab (Accessories+Sheep / Handset, aggregated
    from the product-group exports), this one reads two raw per-line
    flag columns directly off the full TSM sheet -- 'SUPLIFE (PVL)' and
    'IPHONE' -- and keeps SALE_NAME so the tab can offer a salesperson
    view alongside the usual shop/region/area one. Only rows where
    either flag is non-zero are kept (summing zeros doesn't change any
    aggregate), which shrinks ~29k source rows down to a few thousand.

    The same SALE_CODE is sometimes logged with both a Thai name and an
    English/transliterated name on different rows (data entry
    inconsistency upstream). To avoid splitting one salesperson into two
    leaderboard rows, every row's display name is canonicalised here to
    the Thai-script name for that SALE_CODE (falling back to whichever
    name is most common if no Thai-script variant exists).
    """
    f = df[["DATE", "REGION", "AREA", "SHOP_CODE", "SHOP NAME", "TYPE SHOP", "SALE_CODE", "SALE_NAME", "EMP_TYPE", "SUPLIFE (PVL)", "IPHONE", "NET_AMOUNT"]].copy()
    f["SALE_NAME"] = f["SALE_NAME"].astype(str).str.strip()
    f["SALE_CODE"] = f["SALE_CODE"].astype(str).str.strip()

    def is_thai(name):
        return any("\u0e00" <= ch <= "\u0e7f" for ch in name)

    # Resolve the canonical (Thai-preferred) name per SALE_CODE from the
    # FULL sheet, not just the rows that happen to have a non-zero
    # Suplife/iPhone flag -- a salesperson's Thai name may only appear on
    # an unrelated transaction row elsewhere in the same month.
    canonical_name = {}
    for code, names in df.assign(SALE_CODE=df["SALE_CODE"].astype(str).str.strip(), SALE_NAME=df["SALE_NAME"].astype(str).str.strip()).groupby("SALE_CODE")["SALE_NAME"]:
        counts = names.value_counts()
        thai_names = [n for n in counts.index if is_thai(n)]
        canonical_name[code] = thai_names[0] if thai_names else counts.index[0]
    f["SALE_NAME_CANON"] = f["SALE_CODE"].map(canonical_name)

    f["EMP_TYPE"] = f["EMP_TYPE"].fillna("-").astype(str).str.strip().replace("", "-")

    f["SUPLIFE (PVL)"] = pd.to_numeric(f["SUPLIFE (PVL)"], errors="coerce").fillna(0)
    f["IPHONE"] = pd.to_numeric(f["IPHONE"], errors="coerce").fillna(0)
    f["NET_AMOUNT"] = pd.to_numeric(f["NET_AMOUNT"], errors="coerce").fillna(0)
    # A row's NET_AMOUNT belongs to whichever line item it is -- Suplife
    # and iPhone flags never both fire on the same row -- so on a Suplife
    # row this is that Suplife item's own revenue, needed for the
    # commission calculation (Net Amount x %Commission).
    f["SUPLIFE_NET_AMOUNT"] = f["NET_AMOUNT"].where(f["SUPLIFE (PVL)"] != 0, 0.0)
    f = f[(f["SUPLIFE (PVL)"] != 0) | (f["IPHONE"] != 0)]
    f["DATE"] = pd.to_datetime(f["DATE"])

    f = f.sort_values(["DATE", "REGION", "AREA", "SHOP NAME"])
    records = [
        {
            "date": r["DATE"].strftime("%Y-%m-%d"),
            "region": r["REGION"],
            "area": r["AREA"],
            "code": _sc(r["SHOP_CODE"]),
            "shop": str(r["SHOP NAME"]).strip(),
            "type": r["TYPE SHOP"],
            "saleCode": r["SALE_CODE"],
            "saleName": r["SALE_NAME_CANON"],
            "empType": r["EMP_TYPE"],
            "suplife": int(r["SUPLIFE (PVL)"]),
            "suplifeNetAmount": float(r["SUPLIFE_NET_AMOUNT"]),
            "iphone": int(r["IPHONE"]),
        }
        for _, r in f.iterrows()
    ]
    return records

