VIVO_MODEL_COLS = ["VIVO Y05 4G 4/64GB", "VIVO Y05 4G 4/128GB", "VIVO Y11D 4G 4/128GB", "VIVO Y31D 4G 6/128GB", "VIVO Y31D 4G 6/256GB"]
